  "similarities": [
    {
      "point": "Both describe diligence as a legal process for debt recovery.",
      "quote_britannica": "Actions of proving the tenor are, on account of their importance, appropriate to the court of Sellon",
      "quote_wikipedia": "Diligence is a term in Scots law with no single definition but is commonly used to describe debt collection and debt recovery proceedings against a debtor by a creditor in Scottish courts."
    },
    {
      "point": "Both mention that diligence is executed by court officers.",
      "quote_britannica": "Actions proceeded anciently upon brives lifting from the chancery, directed to the judiciary or judge-ordinary, who tried the matter by a jury",
      "quote_wikipedia": "Diligence is usually executed by Sheriff court officers but may also be carried out by messengers-at-arms."
    },
    {
      "point": "Both discuss the role of decrees in legal proceedings.",
      "quote_britannica": "nor an action in which derece is pronounced, because it has got its full completion",
      "quote_wikipedia": "Diligence for enforcement of a non-monetary obligation recognised by a court decree (pronounced 'Dee Cree', known in other jurisdictions as a court order)"
    },
    {
      "point": "Both reference the historical development of legal procedures.",
      "quote_britannica": "But fummonies were, immediately upon the infiltration of the college of Jultices, introduced in the place of brives.",
      "quote_wikipedia": "The history of diligence is obscure, with the first substantial historical research carried out in the 18th century."
    }
  ],
  "differences": [
    {
      "point": "Britannica focuses on proving the tenor of lost writings, while Wikipedia focuses on debt collection.",
      "quote_britannica": "Regularly, no deed can be served by this action, without other animals in writing, referring to that which is libelled",
      "quote_wikipedia": "Diligence is a term in Scots law with no single definition but is commonly used to describe debt collection and debt recovery proceedings against a debtor by a creditor in Scottish courts."
    },
    {
      "point": "Britannica describes ancient brives, while Wikipedia describes modern statutory diligence.",
      "quote_britannica": "Actions proceeded anciently upon brives lifting from the chancery, directed to the judiciary or judge-ordinary",
      "quote_wikipedia": "There are many statutes dealing with the law of debt-related diligences, these include: Debtors (Scotland) Act 1987"
    },
    {
      "point": "Britannica details inducie legator time limits, while Wikipedia details modern debtor protections.",
      "quote_britannica": "The days indulged by law to a defender, between his citation and appearance, to prepare for his defense, are called inducie legator.",
      "quote_wikipedia": "A debtor who is a natural person is entitled to receive a Debt Advice and Information Package when diligence proceedings are raised against him."
    },
    {
      "point": "Britannica discusses actions of multiple pointing, while Wikipedia discusses attachment of property.",
      "quote_britannica": "The action of double or multiple pointing may be also reduced declaratory.",
      "quote_wikipedia": "Attachment is a form of diligence that allows a creditor to seize and sell a debtor's corporeal moveable property"
    }
  ],
  "claims": [
