    {
      "claim": "Defenders in Orkney or Zetland must be cited on forty days.",
      "tag": "dropped",
      "quote_britannica": "Defenders relating in Orkney or Zelians mult be cited on forty days.",
      "quote_wikipedia": null
    },
    {
      "claim": "Spoilzies and ejections proceed on fifteen days.",
      "tag": "dropped",
      "quote_britannica": "Spuilzies and ejections proceed on fifteen days; wakenings",
      "quote_wikipedia": null
    },
    {
      "claim": "An action of transferment transfers an action against a deceased defender to their representative.",
      "tag": "dropped",
      "quote_britannica": "An action of transferment is allo of this fort, whereby an action during the pendency of which the defender happens to die, is craved to be transferenced against his representative",
      "quote_wikipedia": null
    },
    {
      "claim": "A process of wakening applies when an action lies dormant for a year.",
      "tag": "dropped",
      "quote_britannica": "An action is find to flew, when it lies over, not limited in for a year, in which case its effect is lafpend",
      "quote_wikipedia": null
    },
    {
      "claim": "Actions of unanfumng may be purified before any judge-ordinary.",
